  setDeletePartialFiles(settings.value("deletePartialFiles").toBool());
  setEjectCDTray(settings.value("ejectCDTray").toBool());
  setCddbLookupAuto(settings.value("cddbLookupAuto").toBool());
  setCoverLookupAuto(settings.value("coverLookupAuto").toBool());
  setFetchCount(settings.value("fetchCount").toInt());
  setParanoiaMode(settings.value("paranoiaMode").toBool());
  setNeverSkip(settings.value("neverSkip").toBool());
  setSampleOffset(settings.value("sampleOffset").toInt());
  setBasePath(settings.value("basePath").toString());
