void Preferences::showDialog(QWidget* parent, ProfileModel* profileModel)
{
    QDialog dialog(parent);

    QTabWidget* tab = new QTabWidget;

    generalSettingsWidget * page_gen = new generalSettingsWidget();
    page_gen->kcfg_styleDark->setChecked((stylePalette() == "dark"));
    page_gen->kcfg_basePath->setText(basePath());
    page_gen->kcfg_cddbLookupAuto->setChecked(cddbLookupAuto());
    page_gen->kcfg_coverLookupAuto->setChecked(coverLookupAuto());
    page_gen->kcfg_deletePartialFiles->setChecked(deletePartialFiles());
    page_gen->kcfg_ejectCDTray->setChecked(ejectCDTray());
    page_gen->kcfg_fetchCount->setRange(1, 99);
    page_gen->kcfg_fetchCount->setValue(fetchCount());
    page_gen->kcfg_overwriteExistingFiles->setChecked(overwriteExistingFiles());
    tab->addTab(page_gen, tr("General Settings"));

    deviceWidget * page_dev = new deviceWidget();
    page_dev->kcfg_neverSkip->setChecked(neverSkip());
    page_dev->kcfg_paranoiaMode->setChecked(paranoiaMode());
    page_dev->kcfg_sampleOffset->setRange(-10000, +10000);
    page_dev->kcfg_sampleOffset->setValue(sampleOffset());
    tab->addTab(page_dev, tr("Device Settings"));

    profileWidget * page_pro = new profileWidget(profileModel);
    tab->addTab(page_pro, tr("Profiles"));

    // top layout
    QVBoxLayout* topLayout = new QVBoxLayout;

    // add tab
    {
      QHBoxLayout* hLayout = new QHBoxLayout;
      hLayout->addWidget(tab);
      topLayout->addLayout(hLayout, 0);
    }

    // add button box
    QDialogButtonBox * buttonBox = new QDialogButtonBox(QDialogButtonBox::Close);
    buttonBox->setCenterButtons(true);
    connect(buttonBox, SIGNAL(rejected()), &dialog, SLOT(accept()));
    topLayout->addWidget(buttonBox);

    // main grid
    QGridLayout * mainGrid = new QGridLayout;
    mainGrid->addLayout(topLayout, 0, 0);
    dialog.setLayout(mainGrid);

    dialog.exec();

    setStylePalette(page_gen->kcfg_styleDark->isChecked() ? "dark" : "light");
    setBasePath(page_gen->kcfg_basePath->text());
    setCddbLookupAuto(page_gen->kcfg_cddbLookupAuto->isChecked());
    setCoverLookupAuto(page_gen->kcfg_coverLookupAuto->isChecked());
    setDeletePartialFiles(page_gen->kcfg_deletePartialFiles->isChecked());
    setEjectCDTray(page_gen->kcfg_ejectCDTray->isChecked());
    setFetchCount(page_gen->kcfg_fetchCount->value());
    setNeverSkip(page_dev->kcfg_neverSkip->isChecked());
    setOverwriteExistingFiles(page_gen->kcfg_overwriteExistingFiles->isChecked());
    setParanoiaMode(page_dev->kcfg_paranoiaMode->isChecked());
    setSampleOffset(page_dev->kcfg_sampleOffset->value());

    save();
}
